UPDATE "Product" SET "longDescription" = ARRAY['Mélange d''huiles essentielles à l''action calmante. Aide à apaiser le stress et l''anxiété, détend l''esprit et favorise l''endormissement.', 'Composition : Huile essentielle de lavandin (calmante et apaisante) ; Huile essentielle de mandarine (purifiante, antispasmodique et relaxante) ; Huile essentielle d''ylang-ylang (relaxante et aphrodisiaque).', 'Sur la peau : 1 à 2 gouttes sur les tempes pour relâcher les tensions nerveuses.', 'Massage : en cas de tensions musculaires, quelques gouttes dans une huile végétale ou une crème pour le corps.', 'Bain ou douche : 3 à 4 gouttes dans un gel douche neutre pour un effet apaisant.', 'Nettoyant visage : quelques gouttes dans le nettoyant visage pour un effet relaxant.', 'Diffusion : 6 à 7 gouttes pour 300 ml d''eau dans le diffuseur ou le bac du radiateur.', 'Précautions : usage externe ; tenir hors de portée des enfants ; éviter le contact avec les yeux ; déconseillé aux femmes enceintes ou allaitantes et aux jeunes enfants sans avis médical ; faire un essai sur une petite zone de peau avant la première utilisation.']::text[], "updatedAt" = NOW() WHERE "choganCode" = 'LO002' AND (coalesce(cardinality("longDescription"), 0) = 0 OR (cardinality("longDescription") <= 2 AND array_to_string("longDescription", ' ') LIKE '%distribué au Sénégal par JAMAAL%'));
