UPDATE "Product" SET "longDescription" = ARRAY['Mélange d''huiles essentielles à l''action drainante. Aide à éliminer l''excès de liquides responsable de la rétention d''eau, des gonflements et de la cellulite.', 'Composition : Huile essentielle de romarin (stimule la circulation périphérique) ; Huile essentielle de cyprès (aide contre la rétention d''eau et la cellulite) ; Huile essentielle de mandarine (favorise l''élimination des liquides).', 'Massage : 5 à 10 gouttes dans une crème neutre ou une huile de massage ; pour un effet plus intense, quelques gouttes directement sur la zone.', 'Enveloppements : 2 à 3 gouttes dans une boue ou un masque d''argile.', 'Bain délassant : 10 gouttes dans l''eau du bain.', 'Bain de pieds : quelques gouttes dans une bassine d''eau pour dégonfler les pieds.', 'Précautions : usage externe ; tenir hors de portée des enfants ; éviter le contact avec les yeux ; déconseillé aux femmes enceintes ou allaitantes et aux jeunes enfants sans avis médical ; faire un essai sur une petite zone de peau avant la première utilisation.']::text[], "updatedAt" = NOW() WHERE "choganCode" = 'LO005' AND (coalesce(cardinality("longDescription"), 0) = 0 OR (cardinality("longDescription") <= 2 AND array_to_string("longDescription", ' ') LIKE '%distribué au Sénégal par JAMAAL%'));
