UPDATE "Product" SET "longDescription" = ARRAY['Mélange d''huiles végétales apaisant et adoucissant, idéal pour les peaux sensibles et délicates. Atténue les inconforts et les irritations, adoucit la peau et convient particulièrement aux peaux sèches.', 'Composition : Huile de rose musquée (réparatrice et apaisante) ; Huile d''avocat (émolliente, réparatrice et protectrice) ; Huile de chanvre (apaisante et antioxydante) ; Actif exclusif (favorise l''absorption du mélange).', 'Visage : quelques gouttes sur les rougeurs et après le soleil.', 'Corps : quelques gouttes pour hydrater la peau sèche, calmer les démangeaisons et prendre soin des cicatrices et des irritations.', 'Mains : masser les mains abîmées.', 'Précautions : usage externe ; éviter le contact avec les yeux ; faire un essai sur une petite zone de peau avant la première utilisation. Ne remplace pas un avis médical.']::text[], "updatedAt" = NOW() WHERE "choganCode" = 'LO007' AND (coalesce(cardinality("longDescription"), 0) = 0 OR (cardinality("longDescription") <= 2 AND array_to_string("longDescription", ' ') LIKE '%distribué au Sénégal par JAMAAL%'));
