UPDATE "Product" SET "longDescription" = ARRAY['Mélange d''huiles végétales assouplissant et régénérant pour la peau et les cheveux. Redonne tonus et éclat aux peaux ternes et fatiguées ; particulièrement indiqué contre les vergetures et la sécheresse localisée.', 'Composition : Huile d''amande douce (régénérante et assouplissante) ; Huile d''argan (assouplissante) ; Squalane végétal (renforce la barrière cutanée, émollient et assouplissant) ; Actif exclusif (favorise l''absorption du mélange).', 'Cheveux : en masque avant shampooing sur cheveux très secs et abîmés.', 'Corps : léger massage sur la peau ; soin naturel contre les vergetures, pour l''élasticité de la peau.', 'Précautions : usage externe ; éviter le contact avec les yeux ; faire un essai sur une petite zone de peau avant la première utilisation. Ne remplace pas un avis médical.']::text[], "updatedAt" = NOW() WHERE "choganCode" = 'LO008' AND (coalesce(cardinality("longDescription"), 0) = 0 OR (cardinality("longDescription") <= 2 AND array_to_string("longDescription", ' ') LIKE '%distribué au Sénégal par JAMAAL%'));
