UPDATE "Product" SET "longDescription" = ARRAY['Mélange d''huiles végétales antioxydant et illuminateur pour la peau et les cheveux. Aide à préserver la peau de l''oxydation, ravive l''éclat du teint et de la chevelure et atténue les signes de l''âge.', 'Composition : Huile de pépins de raisin (éclaircissante et anti-âge) ; Huile de lin (apaisante et antioxydante) ; Acide hyaluronique (resserre les pores, régule le sébum, atténue les rougeurs) ; Actif exclusif (favorise l''absorption du mélange).', 'Visage : masser jusqu''à absorption pour un effet antioxydant et un teint lumineux.', 'Corps : en huile de massage contre l''aspect peau d''orange et pour stimuler la circulation.', 'Précautions : usage externe ; éviter le contact avec les yeux ; faire un essai sur une petite zone de peau avant la première utilisation. Ne remplace pas un avis médical.']::text[], "updatedAt" = NOW() WHERE "choganCode" = 'LO009' AND (coalesce(cardinality("longDescription"), 0) = 0 OR (cardinality("longDescription") <= 2 AND array_to_string("longDescription", ' ') LIKE '%distribué au Sénégal par JAMAAL%'));
